import ast,datetime,hashlib,importlib.util,json,os,pathlib,re,stat,subprocess,sys
repo=pathlib.Path('/mnt/d/Repo/Virtual_scrum_team')
helper=repo/'tools/qa/s2_runtime_qualification_wsl.py'
candidate_path=repo/'docs/sdlc/evidence/s2-4d-runtime-grant-candidate-558ed80-20261105.json'
EXPECTED_SOURCE_SHA='2c020ef8306c8e9856cf8c7dbf1c83a816d4114320b50b8d9a59bb4b6a7d6666'
raw=helper.read_bytes(); source_sha=hashlib.sha256(raw).hexdigest()
if source_sha!=EXPECTED_SOURCE_SHA: raise SystemExit('FROZEN_WORKTREE_SOURCE_SHA_MISMATCH expected='+EXPECTED_SOURCE_SHA+' actual='+source_sha)
candidate_raw=candidate_path.read_bytes(); candidate=json.loads(candidate_raw)
if 'authorization' in candidate: raise SystemExit('CANDIDATE_CONTAINS_AUTHORIZATION_FIELD')
identity=candidate['identity']; namespace={'hashlib':hashlib,'json':json,'os':os,'re':re,'stat':stat,'subprocess':subprocess,'sys':sys,'EXPECTED_UNITS':None,'AUTH':{'source_pins':candidate['source_pins']},'R':{'commands':[],'terminal':None,'reason':None}}
tree=ast.parse(raw.decode('utf-8','strict'))
selected_names={'_canonical','_pairs','_secure_bytes','_json_file','_tree_digest','_config_identity','_runtime_identity','_prefix','_require_command','stop','_systemd_show','Hold'}
selected=[]
for node in tree.body:
    if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and node.name in selected_names:
        selected.append(node)
    elif isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='EXPECTED_UNITS' for t in node.targets):
        selected.append(node)
found={n.name for n in selected if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))}
if found!=selected_names: raise SystemExit('AST_SELECTION_MISSING '+repr(sorted(selected_names-found)))
exec(compile(ast.Module(body=selected,type_ignores=[]),str(helper),'exec'),namespace)
EXPECTED_UNITS=namespace['EXPECTED_UNITS']; namespace['EXPECTED_UNITS']=EXPECTED_UNITS
if len(EXPECTED_UNITS)!=9: raise SystemExit('EXPECTED_UNIT_COUNT_MISMATCH')
commands=[]
def record(label,argv,*,timeout=30.0,maximum=65536):
    allowed={'/usr/bin/systemctl','show'}
    if len(argv)<3 or argv[0]!='/'+'usr/bin/systemctl' or argv[1]!='show' or argv[2] not in EXPECTED_UNITS:
        raise RuntimeError('READONLY_CALLBACK_REFUSED_NON_SYSTEMCTL_SHOW')
    if commands and len(commands)>=9: raise RuntimeError('READONLY_CALLBACK_COMMAND_LIMIT')
    if not set(argv[3:]) >= {'--property=LoadState','--property=ActiveState','--property=SubState','--property=Result','--property=MainPID','--property=ControlPID','--no-pager'}:
        raise RuntimeError('READONLY_CALLBACK_PROPERTY_SET_MISMATCH')
    started=datetime.datetime.now(datetime.timezone.utc).isoformat()
    p=subprocess.run(argv,cwd='/',env={'LC_ALL':'C','PATH':''},stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=8,check=False,shell=False)
    stdout=p.stdout[:maximum]; stderr=p.stderr[:maximum]
    row={'label':label,'argv':argv,'started_utc':started,'finished_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exit_code':p.returncode,'timed_out':False,'stdout_bytes':len(p.stdout),'stdout_sha256':hashlib.sha256(p.stdout).hexdigest(),'stderr_bytes':len(p.stderr),'stderr_sha256':hashlib.sha256(p.stderr).hexdigest(),'stdout_truncated':len(p.stdout)>len(stdout),'stderr_truncated':len(p.stderr)>len(stderr),'stdout_utf8':stdout.decode('utf-8','backslashreplace'),'stderr_utf8':stderr.decode('utf-8','backslashreplace')}
    commands.append(row)
    return {'id':label,'argv':argv,'started_utc':started,'finished_utc':row['finished_utc'],'exit_code':p.returncode,'timed_out':False,'stdout_bytes':len(p.stdout),'stdout_sha256':row['stdout_sha256'],'stdout_truncated':row['stdout_truncated'],'stderr_bytes':len(p.stderr),'stderr_sha256':row['stderr_sha256'],'stderr_truncated':row['stderr_truncated'],'_stdout':p.stdout,'_stderr':p.stderr}
namespace['record']=record
runtime_check={'passed':False,'error':None}
try:
    namespace['_runtime_identity'](identity); runtime_check['passed']=True
except BaseException as e: runtime_check['error']=type(e).__name__+': '+str(e)[:400]
config_check={'passed':False,'error':None,'task_id':None,'story_id':None,'base_head':None}
try:
    config,bootstrap,manifest=namespace['_config_identity'](identity)
    config_check.update({'passed':True,'task_id':manifest.get('task_id'),'story_id':manifest.get('story_id'),'base_head':manifest.get('base_head'),'bootstrap_request_id':bootstrap.get('request_id'),'run_id':bootstrap.get('run_id')})
except BaseException as e: config_check['error']=type(e).__name__+': '+str(e)[:400]
unit_results={}
for unit in EXPECTED_UNITS:
    try:
        row=namespace['_systemd_show'](unit)
        expected={'LoadState':'loaded','ActiveState':'inactive','SubState':'dead','ControlPID':'0'}
        if not unit.endswith('.socket'): expected['MainPID']='0'
        match=all(row.get(k)==v for k,v in expected.items()) and ('MainPID' not in row or row.get('MainPID')=='0')
        unit_results[unit]={'properties':row,'expected_properties_match':match,'error':None}
    except BaseException as e: unit_results[unit]={'properties':None,'expected_properties_match':False,'error':type(e).__name__+': '+str(e)[:400]}
result={'schema':'VST_S2_4D_QUALIFICATION_PRESTART_READONLY_V1','observed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'candidate_sha256':hashlib.sha256(candidate_raw).hexdigest(),'candidate_schema':candidate.get('schema'),'authorization_present':False,'qualification_source_head_candidate':identity.get('qualification_source_head'),'source_worktree_sha256':source_sha,'source_worktree_differs_from_candidate_qualification_pin':source_sha!=candidate.get('source_pins',{}).get('qualification',{}).get('tools/qa/s2_runtime_qualification_wsl.py'),'runtime_identity_check':runtime_check,'config_identity_check':config_check,'expected_unit_count':len(EXPECTED_UNITS),'systemd_units':unit_results,'systemctl_show_calls':commands,'commands_executed':['/usr/bin/systemctl show']*len(commands),'services_started':0,'qualification_executed':False}
print(json.dumps(result,sort_keys=True,separators=(',',':')),flush=True)
